58	/// A utility class for interacting with Xcode command line tools.
59	class Xcode {
60	  Xcode({
61	    @required Platform platform,
62	    @required ProcessManager processManager,
63	    @required Logger logger,
64	    @required FileSystem fileSystem,
65	    @required XcodeProjectInterpreter xcodeProjectInterpreter,
66	  }) : _platform = platform,
67	       _fileSystem = fileSystem,
68	       _xcodeProjectInterpreter = xcodeProjectInterpreter,
69	       _processUtils = ProcessUtils(logger: logger, processManager: processManager);
70	
71	  final Platform _platform;
72	  final ProcessUtils _processUtils;
73	  final FileSystem _fileSystem;
74	  final XcodeProjectInterpreter _xcodeProjectInterpreter;
75	
76	  bool get isInstalledAndMeetsVersionCheck => _platform.isMacOS && isInstalled && isVersionSatisfactory;
77	
78	  String _xcodeSelectPath;
79	  String get xcodeSelectPath {
80	    if (_xcodeSelectPath == null) {
81	      try {
82	        _xcodeSelectPath = _processUtils.runSync(
83	          <String>['/usr/bin/xcode-select', '--print-path'],
84	        ).stdout.trim();
85	      } on ProcessException {
86	        // Ignored, return null below.
87	      } on ArgumentError {
88	        // Ignored, return null below.
89	      }
90	    }
91	    return _xcodeSelectPath;
92	  }
93	
94	  bool get isInstalled {
95	    if (xcodeSelectPath == null || xcodeSelectPath.isEmpty) {
96	      return false;
97	    }
98	    return _xcodeProjectInterpreter.isInstalled;
99	  }
100	
101	  int get majorVersion => _xcodeProjectInterpreter.majorVersion;
102	  int get minorVersion => _xcodeProjectInterpreter.minorVersion;
103	  int get patchVersion => _xcodeProjectInterpreter.patchVersion;
104	
105	  String get versionText => _xcodeProjectInterpreter.versionText;
106	
107	  bool _eulaSigned;
108	  /// Has the EULA been signed?
109	  bool get eulaSigned {
110	    if (_eulaSigned == null) {
111	      try {
112	        final RunResult result = _processUtils.runSync(
113	          <String>['/usr/bin/xcrun', 'clang'],
114	        );
115	        if (result.stdout != null && result.stdout.contains('license')) {
116	          _eulaSigned = false;
117	        } else if (result.stderr != null && result.stderr.contains('license')) {
118	          _eulaSigned = false;
119	        } else {
120	          _eulaSigned = true;
121	        }
122	      } on ProcessException {
123	        _eulaSigned = false;
124	      }
125	    }
126	    return _eulaSigned;
127	  }
128	
129	  bool _isSimctlInstalled;
130	
131	  /// Verifies that simctl is installed by trying to run it.
132	  bool get isSimctlInstalled {
133	    if (_isSimctlInstalled == null) {
134	      try {
135	        // This command will error if additional components need to be installed in
136	        // xcode 9.2 and above.
137	        final RunResult result = _processUtils.runSync(
138	          <String>['/usr/bin/xcrun', 'simctl', 'list'],
139	        );
140	        _isSimctlInstalled = result.stderr == null || result.stderr == '';
141	      } on ProcessException {
142	        _isSimctlInstalled = false;
143	      }
144	    }
145	    return _isSimctlInstalled;
146	  }
147	
148	  bool get isVersionSatisfactory {
149	    if (!_xcodeProjectInterpreter.isInstalled) {
150	      return false;
151	    }
152	    if (majorVersion > kXcodeRequiredVersionMajor) {
153	      return true;
154	    }
155	    if (majorVersion == kXcodeRequiredVersionMajor) {
156	      if (minorVersion == kXcodeRequiredVersionMinor) {
157	        return patchVersion >= kXcodeRequiredVersionPatch;
158	      }
159	      return minorVersion >= kXcodeRequiredVersionMinor;
160	    }
161	    return false;
162	  }
163	
164	  Future<RunResult> cc(List<String> args) {
165	    return _processUtils.run(
166	      <String>['xcrun', 'cc', ...args],
167	      throwOnError: true,
168	    );
169	  }
170	
171	  Future<RunResult> clang(List<String> args) {
172	    return _processUtils.run(
173	      <String>['xcrun', 'clang', ...args],
174	      throwOnError: true,
175	    );
176	  }
177	
178	  Future<String> sdkLocation(SdkType sdk) async {
179	    assert(sdk != null);
180	    final RunResult runResult = await _processUtils.run(
181	      <String>['xcrun', '--sdk', getNameForSdk(sdk), '--show-sdk-path'],
182	    );
183	    if (runResult.exitCode != 0) {
184	      throwToolExit('Could not find SDK location: ${runResult.stderr}');
185	    }
186	    return runResult.stdout.trim();
187	  }
188	
189	  String getSimulatorPath() {
190	    if (xcodeSelectPath == null) {
191	      return null;
192	    }
193	    final List<String> searchPaths = <String>[
194	      _fileSystem.path.join(xcodeSelectPath, 'Applications', 'Simulator.app'),
195	    ];
196	    return searchPaths.where((String p) => p != null).firstWhere(
197	      (String p) => _fileSystem.directory(p).existsSync(),
198	      orElse: () => null,
199	    );
200	  }
201	}
