101	  if (!upgradePbxProjWithFlutterAssets(app.project, globals.logger)) {
102	    return XcodeBuildResult(success: false);
103	  }
104	
105	  final List<IOSMigrator> migrators = <IOSMigrator>[
106	    RemoveFrameworkLinkAndEmbeddingMigration(app.project, globals.logger, globals.xcode, globals.flutterUsage),
107	    XcodeBuildSystemMigration(app.project, globals.logger),
108	    ProjectBaseConfigurationMigration(app.project, globals.logger),
109	  ];
110	
111	  final IOSMigration migration = IOSMigration(migrators);
112	  if (!migration.run()) {
113	    return XcodeBuildResult(success: false);
114	  }
115	
116	  if (!_checkXcodeVersion()) {
117	    return XcodeBuildResult(success: false);
118	  }
119	
120	  await removeFinderExtendedAttributes(app.project.hostAppRoot, globals.processUtils, globals.logger);
121	
122	  final XcodeProjectInfo projectInfo = await app.project.projectInfo();
123	  final String scheme = projectInfo.schemeFor(buildInfo);
124	  if (scheme == null) {
125	    projectInfo.reportFlavorNotFoundAndExit();
126	  }
127	  final String configuration = projectInfo.buildConfigurationFor(buildInfo, scheme);
128	  if (configuration == null) {
129	    globals.printError('');
130	    globals.printError('The Xcode project defines build configurations: ${projectInfo.buildConfigurations.join(', ')}');
131	    globals.printError('Flutter expects a build configuration named ${XcodeProjectInfo.expectedBuildConfigurationFor(buildInfo, scheme)} or similar.');
132	    globals.printError('Open Xcode to fix the problem:');
133	    globals.printError('  open ios/Runner.xcworkspace');
134	    globals.printError('1. Click on "Runner" in the project navigator.');
135	    globals.printError('2. Ensure the Runner PROJECT is selected, not the Runner TARGET.');
136	    if (buildInfo.isDebug) {
137	      globals.printError('3. Click the Editor->Add Configuration->Duplicate "Debug" Configuration.');
138	    } else {
139	      globals.printError('3. Click the Editor->Add Configuration->Duplicate "Release" Configuration.');
140	    }
141	    globals.printError('');
142	    globals.printError('   If this option is disabled, it is likely you have the target selected instead');
143	    globals.printError('   of the project; see:');
144	    globals.printError('   https://stackoverflow.com/questions/19842746/adding-a-build-configuration-in-xcode');
145	    globals.printError('');
146	    globals.printError('   If you have created a completely custom set of build configurations,');
147	    globals.printError('   you can set the FLUTTER_BUILD_MODE=${buildInfo.modeName.toLowerCase()}');
148	    globals.printError('   in the .xcconfig file for that configuration and run from Xcode.');
149	    globals.printError('');
150	    globals.printError('4. If you are not using completely custom build configurations, name the newly created configuration ${buildInfo.modeName}.');
151	    return XcodeBuildResult(success: false);
152	  }
153	
154	  final FlutterManifest manifest = app.project.parent.manifest;
155	  final String buildName = parsedBuildName(manifest: manifest, buildInfo: buildInfo);
156	  final bool buildNameIsMissing = buildName == null || buildName.isEmpty;
157	
158	  if (buildNameIsMissing) {
159	    globals.printStatus('Warning: Missing build name (CFBundleShortVersionString).');
160	  }
161	
162	  final String buildNumber = parsedBuildNumber(manifest: manifest, buildInfo: buildInfo);
